checkRuns.command:
cat > app/pages/contact.vue <<'EOF'
<script setup lang="ts">
useHead({ title: 'Contact | Bookshelf' })

interface ContactState {
  values: ContactValues
  errors: ContactErrors
  success: string
}

const emptyState = (): ContactState => ({
  values: { name: '', email: '', message: '' },
  errors: {},
  success: '',
})

const state = useState<ContactState>('contact', emptyState)

// Without JavaScript the form posts here: validate on the server and render the result.
if (import.meta.server) {
  const event = useRequestEvent()
  if (event?.method === 'POST') {
    const values = normalizeContact(await readBody(event).catch(() => ({})))
    const errors = validateContact(values)
    const valid = Object.keys(errors).length === 0
    state.value = {
      values: valid ? { name: '', email: '', message: '' } : values,
      errors,
      success: valid ? successMessage(values.name) : '',
    }
    if (!valid) setResponseStatus(event, 422)
  }
}

onBeforeUnmount(() => {
  state.value = emptyState()
})

const sending = ref(false)

async function onSubmit() {
  const values = { ...state.value.values }
  const errors = validateContact(values)
  state.value.errors = errors
  state.value.success = ''
  if (Object.keys(errors).length > 0) return

  sending.value = true
  try {
    const result = await $fetch('/api/contact', {
      method: 'POST',
      body: values,
      ignoreResponseError: true,
    })
    if (result.ok) {
      state.value = { ...emptyState(), success: result.message }
    } else {
      state.value.errors = result.errors
    }
  } catch {
    state.value.errors = {}
  } finally {
    sending.value = false
  }
}
</script>

<template>
  <div>
    <h1>Contact</h1>

    <p v-if="state.success" class="success" role="status">{{ state.success }}</p>

    <form method="post" action="/contact" novalidate @submit.prevent="onSubmit">
      <div class="field">
        <label for="contact-name">Name</label>
        <input
          id="contact-name"
          v-model="state.values.name"
          type="text"
          name="name"
          autocomplete="name"
          :aria-invalid="state.errors.name ? 'true' : undefined"
          :aria-describedby="state.errors.name ? 'contact-name-error' : undefined"
        >
        <p v-if="state.errors.name" id="contact-name-error" class="error">{{ state.errors.name }}</p>
      </div>

      <div class="field">
        <label for="contact-email">Email</label>
        <input
          id="contact-email"
          v-model="state.values.email"
          type="email"
          name="email"
          autocomplete="email"
          :aria-invalid="state.errors.email ? 'true' : undefined"
          :aria-describedby="state.errors.email ? 'contact-email-error' : undefined"
        >
        <p v-if="state.errors.email" id="contact-email-error" class="error">{{ state.errors.email }}</p>
      </div>

      <div class="field">
        <label for="contact-message">Message</label>
        <textarea
          id="contact-message"
          v-model="state.values.message"
          name="message"
          rows="6"
          :aria-invalid="state.errors.message ? 'true' : undefined"
          :aria-describedby="state.errors.message ? 'contact-message-error' : undefined"
        />
        <p v-if="state.errors.message" id="contact-message-error" class="error">{{ state.errors.message }}</p>
      </div>

      <button type="submit" :disabled="sending">Send</button>
    </form>
  </div>
</template>
EOF
rm -rf app/components; bunx nuxt prepare 2>&1 | tail -5; bun run check 2>&1 | tail -30
